========== native-edge-menu.ts ==========
import { NativeModules, Platform } from "react-native";

type NativeEdgeMenuModule = {
  openMenu?: () => void;
  closeMenu?: () => void;
};

const module = NativeModules.NativeEdgeMenu as NativeEdgeMenuModule | undefined;

export const nativeEdgeMenuAvailable = Platform.OS === "ios" && !!module;

export const openNativeEdgeMenu = () => {
  module?.openMenu?.();
};

export const closeNativeEdgeMenu = () => {
  module?.closeMenu?.();
};

========== native-menu-root.tsx ==========
import { SafeAreaProvider } from "react-native-safe-area-context";

import { resetMainStackToScreen, type MainStackParamList } from "../navigation";
import { MenuContent } from "../screens/menu-screen";
import { closeNativeEdgeMenu } from "./native-edge-menu";

type OpenScreen = <Screen extends keyof MainStackParamList>(
  screen: Screen,
  params?: MainStackParamList[Screen]
) => void;

export const NativeMenuRoot = () => {
  const openScreen: OpenScreen = (screen, params) => {
    resetMainStackToScreen(screen, params);
    closeNativeEdgeMenu();
  };

  return (
